package com.yuri.music;
import android.app.Activity;import android.content.Intent;import android.content.pm.*;import android.net.Uri;import android.os.Build;import android.provider.Settings;import androidx.core.content.FileProvider;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;
final class AppUpdates {
 static final String CURRENT="0.8.0",API="https://api.github.com/repos/yuri434/yuri-music/releases/latest";
 final Activity activity;boolean busy;AppUpdates(Activity a){activity=a;}
 static int[] version(String s)throws IOException{if(s==null||!s.matches("v?\\d+\\.\\d+\\.\\d+"))throw new IOException("Versão inválida.");String[] p=s.replaceFirst("^v","").split("\\.");return new int[]{Integer.parseInt(p[0]),Integer.parseInt(p[1]),Integer.parseInt(p[2])};}
 static boolean newer(String a,String b)throws IOException{int[] x=version(a),y=version(b);for(int i=0;i<3;i++){if(x[i]!=y[i])return x[i]>y[i];}return false;}
 static boolean allowed(URL u){return u.getProtocol().equals("https")&&Arrays.asList("github.com","api.github.com","release-assets.githubusercontent.com","objects.githubusercontent.com").contains(u.getHost());}
 static HttpURLConnection open(String address)throws Exception{for(int i=0;i<6;i++){URL u=new URL(address);if(!allowed(u))throw new IOException("Origem da atualização inválida.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(45000);c.setRequestProperty("User-Agent","YuriMusic/"+CURRENT);c.setRequestProperty("Accept","application/vnd.github+json");int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException("Redirecionamento inválido.");address=new URL(u,next).toString();continue;}if(status!=200){c.disconnect();throw new IOException("Não foi possível consultar ou baixar a atualização. Tente mais tarde.");}return c;}throw new IOException("Redirecionamentos demais.");}
 static byte[] read(String url,int limit)throws Exception{HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Arquivo muito grande.");out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();}}
 static JSONObject latest()throws Exception{JSONObject r=new JSONObject(new String(read(API,2097152),StandardCharsets.UTF_8));version(r.getString("tag_name"));if(r.optBoolean("draft")||r.optBoolean("prerelease"))throw new IOException("Versão indisponível.");return r;}
 static String asset(JSONObject r,String name)throws Exception{JSONArray assets=r.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(a.getString("name").equals(name)){String link=a.getString("browser_download_url");URL u=new URL(link);if(!u.getProtocol().equals("https")||!u.getHost().equals("github.com")||!u.getPath().startsWith("/yuri434/yuri-music/releases/download/"))throw new IOException("Link de atualização inválido.");return link;}}throw new IOException("Os arquivos da atualização ainda estão sendo preparados.");}
 JSONObject check()throws Exception{JSONObject r=latest();String latest=r.getString("tag_name").replaceFirst("^v","");boolean available=newer(latest,CURRENT),ready=false;if(available)try{asset(r,"YuriMusic-Android-"+latest+".apk");asset(r,"SHA256SUMS-"+latest+".txt");ready=true;}catch(Exception ignored){}return new JSONObject().put("current",CURRENT).put("latest",latest).put("available",available).put("ready",ready).put("platform","android").put("message",available?(ready?"Versão "+latest+" disponível.":"A nova versão está sendo preparada. Tente depois."):"Você está na versão mais recente.");}
 static String hex(byte[] value){StringBuilder s=new StringBuilder();for(byte b:value)s.append(String.format(Locale.ROOT,"%02x",b));return s.toString();}
 static String hash(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}return hex(digest.digest());}
 static String expected(String sums,String name)throws IOException{for(String line:sums.split("\n")){String[] parts=line.trim().split("\\s+",2);if(parts.length==2&&parts[0].matches("[a-fA-F0-9]{64}")&&parts[1].replaceFirst("^\\*","").equals(name))return parts[0].toLowerCase(Locale.ROOT);}throw new IOException("Verificação de integridade ausente.");}
 @SuppressWarnings("deprecation")void verifyPackage(File apk)throws Exception{PackageManager pm=activity.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo installed=pm.getPackageInfo(activity.getPackageName(),flags),downloaded=pm.getPackageArchiveInfo(apk.getAbsolutePath(),flags);if(downloaded==null||!activity.getPackageName().equals(downloaded.packageName)||!newer(downloaded.versionName,installed.versionName))throw new IOException("O APK não é uma atualização válida deste aplicativo.");Signature[] a=Build.VERSION.SDK_INT>=28?installed.signingInfo.getApkContentsSigners():installed.signatures,b=Build.VERSION.SDK_INT>=28?downloaded.signingInfo.getApkContentsSigners():downloaded.signatures;if(a==null||b==null||a.length!=b.length)throw new IOException("Assinatura diferente.");Set<String> signatures=new HashSet<>();for(Signature s:a)signatures.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));for(Signature s:b)if(!signatures.contains(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray()))))throw new IOException("A assinatura do APK não corresponde ao aplicativo instalado.");}
 JSONObject install(String wanted)throws Exception{synchronized(this){if(busy)throw new IOException("Uma atualização já está em andamento.");busy=true;}try{JSONObject r=latest();String v=r.getString("tag_name").replaceFirst("^v","");if(!v.equals(wanted)||!newer(v,CURRENT))throw new IOException("Confira novamente as atualizações antes de instalar.");String name="YuriMusic-Android-"+v+".apk",url=asset(r,name),checksum=expected(new String(read(asset(r,"SHA256SUMS-"+v+".txt"),65536),StandardCharsets.UTF_8),name);File dir=new File(activity.getCacheDir(),"updates");dir.mkdirs();File apk=new File(dir,name);if(!apk.isFile()||!hash(apk).equals(checksum)){File part=new File(dir,name+".part");HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(part)){byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>300L*1024*1024)throw new IOException("Atualização muito grande.");out.write(b,0,n);}out.getFD().sync();}finally{c.disconnect();}if(!hash(part).equals(checksum)){part.delete();throw new IOException("O download não passou na verificação. Tente novamente.");}if(apk.exists()&&!apk.delete())throw new IOException("Não foi possível preparar o APK.");if(!part.renameTo(apk))throw new IOException("Não foi possível preparar o APK.");}verifyPackage(apk);CompletableFuture<JSONObject> result=new CompletableFuture<>();activity.runOnUiThread(()->{try{if(!activity.getPackageManager().canRequestPackageInstalls()){activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));result.complete(new JSONObject().put("message","Autorize instalar atualizações e volte ao app. Depois toque em Atualizar novamente."));}else{Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".updates",apk);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);result.complete(new JSONObject().put("message","Confirme a atualização na tela do Android."));}}catch(Exception error){result.completeExceptionally(error);}});return result.get(15,TimeUnit.SECONDS);}finally{synchronized(this){busy=false;}}}
}
